def review():
    guard();dest=OUT/'composite_qualification_review.json';assert not dest.exists();rows=[{'revision':rev,**r} for rev in ['w0','w1'] for r in read(OUT/f'native_case_summary_{rev}.json')['cases']];assert len(rows)==22
    h={k:v for k,v in np.load(OUT/'w1/FREE_ROTATION_Y_N12/histories_SI.npz').items()};h2={k:v for k,v in np.load(OUT/'w1/FREE_ROTATION_Y_N12_HALF/histories_SI.npz').items()};mask=(h['time_ms']>=h2['time_ms'][0])&(h['time_ms']<=h2['time_ms'][-1]);T=h['time_ms'][mask];ld=float(np.linalg.norm(h['physical_L_kg_m2_s'][mask]-np.column_stack([np.interp(T,h2['time_ms'],h2['physical_L_kg_m2_s'][:,a]) for a in range(3)]),axis=1).max());ed=float(abs(h['total_J'][mask]-np.interp(T,h2['time_ms'],h2['total_J'])).max());ratio=float(np.median(h2['time_step_ms'][1:])/np.median(h['time_step_ms'][1:]));dt={'actual_dt_ratio':ratio,'physical_L_difference_kg_m2_s':ld,'energy_difference_J':ed,'checks':{'actually_shorter':ratio<.6,'L_converges':bool(ld<.002*np.linalg.norm(h['physical_L_kg_m2_s'][0])+1e-9),'energy_converges':bool(ed<.002*h['total_J'][0]+1e-7)}}
    mesh=[]
    for motion in ['MEMBRANE','BENDING']:
        a=read(OUT/'w1'/f'{motion}_N6/review.json');b=read(OUT/'w1'/f'{motion}_N12/review.json');diff=abs(a['native_elastic_comparison_J']-b['native_elastic_comparison_J'])/b['native_elastic_comparison_J'];mesh.append({'motion':motion,'difference_fraction':diff,'pass':diff<.05,'N6':a,'N12':b})
    samples=[];layers=[];stress=[]
    for rev in ['w0','w1']:
        for d in sorted((OUT/rev).iterdir()):
            g=read(d/'generation.json');X=np.asarray(g['nodes_mm']);n=g['name'];s=(d/(n+'_0000.out')).read_text();pos=[float(z.replace('D','E')) for z in re.findall(r'POSITION  \(\[-0\.5,\+0\.5\]\).*?=\s*([+\-0-9.E]+)',s)];exp=(np.arange(9)+.5)/9-.5;assert len(pos)==9
            m=re.search(r'Isolid  Ismstr   Icpre     NPT ICONTROL\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)',s);assert m
            checks={'positions':bool(np.allclose(pos,exp,atol=2e-11,rtol=0)),'zero_warnings':read(d/'starter_gate.json')['pass'],'known_mass':abs(g['known_mass_g']-.0915)<1e-10};layers.append({'revision':rev,'case':d.name,'positions':pos,'part_readback_Isolid_Ismstr_Icpre_NPT_Icontrol':list(map(int,m.groups())),'checks':checks,'pass':all(checks.values())})
            native=sorted(p for p in d.glob(n+'A*') if re.fullmatch(re.escape(n)+r'A\d{3}',p.name));assert native
            for p in sorted(set([native[0],native[len(native)//2],native[-1]])):
                ad=OUT/'native_field_audit'/rev/d.name;ad.mkdir(parents=True,exist_ok=True);v=ad/(p.name+'.vtk');assert not v.exists();res=subprocess.run([str(RUNTIME/'anim_to_vtk_win64.exe'),str(p)],capture_output=True,text=True,check=True,timeout=120);v.write_text(res.stdout,encoding='utf-8');q=vtk(v.read_text(encoding='utf-8'));order=np.argsort(q['NODE_ID']);pts=q['points'].reshape(-1,3)[order];disp=q['Displacement'].reshape(-1,3)[order];vel=q['Velocity'].reshape(-1,3)[order];bound=printed_bound(pts)+printed_bound(disp)+4*np.finfo(np.float32).eps*np.maximum.reduce([abs(pts),abs(disp),abs(X)])+1e-8;checks={'ids':bool(np.array_equal(q['NODE_ID'][order],np.arange(1,len(X)+1))),'finite':bool(np.isfinite(pts).all() and np.isfinite(disp).all() and np.isfinite(vel).all()),'identity_with_printing_bound':bool(np.all(abs(pts-X-disp)<=bound)),'no_eroded_elements':bool(np.all(q['EROSION_STATUS']==1))};samples.append({'revision':rev,'case':d.name,'time_ms':q['time'],'native':rel(p),'native_sha256':streamsha(p),'vtk':rel(v),'vtk_sha256':streamsha(v),'checks':checks,'pass':all(checks.values())})
                if p==native[-1] and d.name.startswith('PATCH_'):
                    S=q['3DELEM_Stress'].reshape(-1,3,3);stress.append({'revision':rev,'case':d.name,'time_ms':q['time'],'vtk':rel(v),'native_global_stress_MPa_mean':S.mean(axis=0).tolist(),'native_global_stress_MPa_min':S.min(axis=0).tolist(),'native_global_stress_MPa_max':S.max(axis=0).tolist(),'declared_stress_Voigt_MPa':(constitutive()@patch_strain(d.name)).tolist(),'qualification':'diagnostic comparison, no new post-run acceptance threshold'})
    dump(OUT/'native_fields_review.json',{'created_utc':now(),'samples':samples,'pass':all(r['pass'] for r in samples),'solver_thresholds_unchanged':True,'native_reruns':0});dump(OUT/'layer_readback_review.json',{'created_utc':now(),'cases':layers,'pass':all(r['pass'] for r in layers)});dump(OUT/'affine_native_stress_observation.json',{'created_utc':now(),'cases':stress,'general_3D_equivalence_claimed':False})
