    candidate=[r for r in rows if r['revision']=='w1'];checks={'candidate_all_native_gates':all(r['pass'] for r in candidate),'time_refinement':all(dt['checks'].values()),'spatial_mesh':all(r['pass'] for r in mesh),'native_fields':all(r['pass'] for r in samples),'layer_readback':all(r['pass'] for r in layers)};dump(dest,{'created_utc':now(),'cases':rows,'candidate_revision':'w1','refinement':dt,'mesh':mesh,'checks':checks,'composite_prototype_pass':all(checks.values()),'free_and_membrane_scope_pass':all(r['pass'] for r in candidate if r['case'].startswith(('FREE','MEMBRANE'))),'bending_scope_pass':all(r['pass'] for r in candidate if r['case'].startswith('BENDING')),'shear_scope_pass':all(r['pass'] for r in candidate if r['case'].startswith('PATCH_SHEAR')),'cached_A27_ASQBI_prediction_matches':read(OUT/'assumed_strain_diagnostic.json')['prediction_matches_all'],'global_Icpre1_not_applied_to_part':all(x['part_readback_Isolid_Ismstr_Icpre_NPT_Icontrol'][2]==3 for x in layers if x['revision']=='w0'),'whole_insertion_ready':False,'objective1_complete':False});print({'A28_review':checks,'prototype_qualified':all(checks.values())},flush=True)

